 // registerCognitiveRoutes registers Cognitive Engine-related routes
 func (ar *APIRouter) registerCognitiveRoutes(apiV1 *mux.Router) {
 	cognitiveRouter := apiV1.PathPrefix("/cognitive").Subrouter()

